function storyMarkup(p){return `<section class="notebook-story" id="story"><div class="section-label"><span>01 / ${t('DENTRO IL PROGETTO','INSIDE THE PROJECT')}</span><span>${t('Idea → spazio → dettaglio','Idea → space → detail')}</span></div><div class="story-grid"><aside><span class="personal-mark">F/V — ${t('APPUNTI DI PROGETTO','PROJECT NOTES')}</span><h2>${v(p.question)}</h2><p>${v(p.lens)}</p><span class="hand-note">${t('dalle persone,<br>alla forma.','from people,<br>to form.')}</span></aside><div class="story-chapters">${p.chapters.map((c,i)=>`<details ${i===0?'open':''}><summary><span>${num(i+1)}</span><h3>${v(c.title)}</h3><b>+</b></summary><p>${v(c.body)}</p></details>`).join('')}</div></div></section>`}
function atlasMarkup(p){const labels={all:t('Tutte','All'),plan:t('Piante','Plans'),section:t('Sezioni / Prospetti','Sections / Elevations'),detail:t('Dettagli / Materiali','Details / Materials'),board:t('Tavole','Boards')};const kinds=['all',...new Set(p.technical.map(s=>s.kind))];return `<section class="technical-atlas" id="atlas"><div class="section-label"><span>02 / ${t('ATLANTE TECNICO','TECHNICAL ATLAS')}</span><span>${p.technical.length} ${t('elaborati','drawings')}</span></div><div class="atlas-heading"><h2>${t('Dal pensiero<br>alla costruzione.','From thought<br>to construction.')}</h2><p>${t('Piante, sezioni e dettagli originali.<br>Scegli una tavola, avvicinati, esplora.','Original plans, sections and details.<br>Choose a drawing, zoom in, explore.')}</p></div><div class="atlas-filters" aria-label="${t('Tipo di elaborato','Drawing type')}">${kinds.map((k,i)=>`<button data-filter="${k}" aria-pressed="${i===0}">${labels[k]}</button>`).join('')}</div><div class="atlas-toolbar"><label for="drawing-select">${t('Elaborato','Drawing')}<select id="drawing-select">${p.technical.map((s,i)=>`<option value="${i}">${num(i+1)} — ${v(s.title)}</option>`).join('')}</select></label><div class="atlas-zoom"><button id="zoom-out" aria-label="${t('Riduci','Zoom out')}">−</button><output id="zoom-value">100%</output><button id="zoom-in" aria-label="${t('Ingrandisci tavola','Zoom in')}">+</button><button id="zoom-fit">${t('Adatta','Fit')}</button></div></div><div class="technical-stage" tabindex="0" role="region" aria-label="${t('Tavola esplorabile: usa le barre di scorrimento dopo lo zoom','Drawing viewer: use scrollbars after zooming')}"><div class="technical-paper">${image(p.technical[0].image,v(p.technical[0].title))}</div></div><div class="atlas-bottom"><div><button id="drawing-prev" aria-label="${t('Tavola precedente','Previous drawing')}">←</button><span id="drawing-count">01 / ${num(p.technical.length)}</span><button id="drawing-next" aria-label="${t('Tavola successiva','Next drawing')}">→</button></div><span id="drawing-status" aria-live="polite">${v(p.technical[0].title)}</span><button id="drawing-full">${t('Schermo intero','Full screen')} ↗</button><a id="drawing-download" href="${asset(p.technical[0].image)}" download>${t('Scarica','Download')} ↓</a></div><p class="atlas-note">${t('Elaborati originali del progetto. Le scritte integrate nelle tavole mantengono la lingua originale.','Original project drawings. Text embedded in the drawings retains its original language.')}</p></section>`}
function bindNotebook(p){let visible=p.technical.map((_,i)=>i),current=0,zoom=1;const select=main.querySelector('#drawing-select'),stage=main.querySelector('.technical-stage'),paper=main.querySelector('.technical-paper');galleryItems.push(...p.technical.map(s=>s.image));
 function scale(n){zoom=Math.max(1,Math.min(3,n));paper.style.width=(zoom*100)+'%';paper.style.height=(zoom*100)+'%';main.querySelector('#zoom-value').textContent=Math.round(zoom*100)+'%';main.querySelector('#zoom-out').disabled=zoom===1;main.querySelector('#zoom-in').disabled=zoom===3;if(zoom===1)stage.scrollTo(0,0)}
 function show(i){current=i;const s=p.technical[i],im=paper.querySelector('img');im.src=asset(s.image);im.alt=v(s.title);select.value=String(i);main.querySelector('#drawing-count').textContent=`${num(visible.indexOf(i)+1)} / ${num(visible.length)}`;main.querySelector('#drawing-status').textContent=v(s.title);main.querySelector('#drawing-download').href=asset(s.image);scale(1)}
 select.onchange=()=>show(+select.value);main.querySelector('#zoom-in').onclick=()=>scale(zoom+.5);main.querySelector('#zoom-out').onclick=()=>scale(zoom-.5);main.querySelector('#zoom-fit').onclick=()=>scale(1);main.querySelector('#drawing-prev').onclick=()=>show(visible[(visible.indexOf(current)-1+visible.length)%visible.length]);main.querySelector('#drawing-next').onclick=()=>show(visible[(visible.indexOf(current)+1)%visible.length]);main.querySelector('#drawing-full').onclick=()=>openLight(p.gallery.length+1+current);
 main.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{visible=p.technical.map((s,i)=>b.dataset.filter==='all'||s.kind===b.dataset.filter?i:-1).filter(i=>i>=0);select.innerHTML=visible.map(i=>`<option value="${i}">${num(i+1)} — ${v(p.technical[i].title)}</option>`).join('');main.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));show(visible[0])});
 main.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>{const target=b.dataset.scroll==='gallery'?main.querySelector('.gallery'):main.querySelector('#'+b.dataset.scroll);target.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'})});scale(1);
 if(p.id==='monoblock'){window.chapterDescriptions=[P('La sedia monoblocco racconta una produzione industriale capace di ottimizzare forma, tempo e costo.','The monobloc chair tells the story of industrial production optimising form, time and cost.'),P('La materia rimane dopo l’uso. Il percorso interroga la distanza tra possibilità di recupero e infrastrutture reali.','Matter remains after use. The journey questions the gap between recovery possibilities and actual infrastructure.'),P('Le sei stampanti producono senza una domanda: gli oggetti cadono a terra e si accumulano. La mostra rende visibile il limite di un progetto che termina con la produzione.','Six printers produce without demand: objects fall to the floor and accumulate. The exhibition exposes the limits of design that ends at production.')]}
 const chapter=main.querySelector('.chapter');if(chapter&&p.id!=='bivacuum'){const names=p.id==='monoblock'?['monoblock-33','monoblock-37','monoblock-39']:p.id==='oltreetrusco'?['oltre-sala1','oltre-sala2','oltre-sala3a']:['soundplace_storyboard','soundplace_assonometria','soundplace_render_parco'];const visual=document.createElement('div');visual.className='stage-visual';visual.innerHTML=image(names[0],caption(names[0]));chapter.append(visual);chapter.addEventListener('click',e=>{const b=e.target.closest('[data-stage]');if(b){const im=visual.querySelector('img'),name=names[+b.dataset.stage];im.src=asset(name);im.alt=caption(name)}})}
}
